import { expect, expectStatus, test, uniqueName, type Vendor } from "../../fixtures";

test("search and the status filter apply together", { tag: "@LIF-14" }, async ({ apiAs, factory }) => {
  // Arrange: two vendors sharing one unique word, one draft and one in review
  const word = uniqueName("Lifecycle").replace(/\s+/g, "");
  const draft = await factory.vendor({ name: `${word} Draft` });
  const review = await factory.vendorInReview({ name: `${word} Review` });
  const member = await apiAs("member");

  // Act
  const response = await member.get("/api/vendors", { params: { q: word, status: "in_review" } });

  // Assert
  const page = await expectStatus<{ items: Vendor[]; total: number }>(response, 200);
  expect(review.vendor.status).toBe("in_review");
  expect(page.items.map((v) => v.id)).toEqual([review.vendor.id]);
  expect(page.items.map((v) => v.id)).not.toContain(draft.id);
  expect(page.total).toBe(1);
});
